/* BASE GLITCH BOT — compact premium skin */
(function(){
 const BRAND="BASE GLITCH BOT", TELEGRAM="https://t.me/ayyan_trader02";
 function apply(){
  if(!document.getElementById("mughal-root")) return;
  if(!document.getElementById("base-glitch-theme")){
   const st=document.createElement("style"); st.id="base-glitch-theme";
   st.textContent=`
   #mughal-root{--bg:#080d18;--panel:#0e1728;--line:rgba(148,163,184,.18);font-family:Inter,system-ui,-apple-system,sans-serif!important;color:#e8eef9!important}
   #mughal-root .app-card,#mughal-root .license-gate-card{background:linear-gradient(145deg,#101b2e,#080e1b)!important;border:1px solid rgba(56,189,248,.28)!important;border-radius:14px!important;box-shadow:0 18px 55px rgba(0,0,0,.48),0 0 24px rgba(14,165,233,.07)!important}
   #mughal-root .panel-header,#mughal-root .license-gate-header{padding:9px 12px!important;border-bottom:1px solid var(--line)!important}
   #mughal-root .app-card{width:min(340px,calc(100vw - 20px))!important;max-width:calc(100vw - 20px)!important}
   #mughal-root button,#mughal-root .chip,#mughal-root input,#mughal-root select{border-radius:8px!important;font-size:11px!important}
   #mughal-root button{padding:7px 10px!important;transition:all .18s ease!important}
   #mughal-root input,#mughal-root select{padding:8px 9px!important;background:#080f1d!important;color:#e8eef9!important;border:1px solid var(--line)!important}
   #mughal-root .minimized-pill{transform:scale(.88);transform-origin:bottom right}
   #mughal-root .footer-minimize-prompt{font-size:9px!important;letter-spacing:1.6px!important;color:#7dd3fc!important}
   #mughal-root a.btn-contact-telegram{background:linear-gradient(100deg,rgba(14,165,233,.16),rgba(99,102,241,.13))!important;border:1px solid rgba(56,189,248,.35)!important;color:#bae6fd!important;padding:8px!important;border-radius:8px!important;font-size:10px!important}
   #mughal-root .logo-frame{border-radius:10px!important;overflow:hidden}
   @media(max-width:480px){#mughal-root .app-card{width:calc(100vw - 16px)!important;left:8px!important}#mughal-root .panel-header{padding:7px 9px!important}}
   `;
   document.head.appendChild(st);
  }
  document.querySelectorAll('#mughal-root a.btn-contact-telegram').forEach(a=>{a.href=TELEGRAM;a.target="_blank";a.rel="noopener noreferrer";a.innerHTML='↗ &nbsp; GET KEY ON TELEGRAM';});
  document.querySelectorAll('#mughal-root [placeholder*="MUGHAL"],#mughal-root [placeholder*="Mughal"]').forEach(e=>e.placeholder="Enter BASE GLITCH BOT key");
  document.querySelectorAll('#mughal-root [aria-label="MUGHAL"]').forEach(e=>e.setAttribute("aria-label",BRAND));
 }
 apply(); new MutationObserver(apply).observe(document.documentElement,{childList:true,subtree:true});
})();
